// usage: node gen.mjs <outfile> <casesModule>
// casesModule default-exports an array of [instance, schema] pairs (real JS values)
import { writeFileSync } from 'node:fs';
const out = process.argv[2];
const mod = await import(process.argv[3]);
const cases = mod.default.map(([i, s]) => ({ a: JSON.stringify(i), b: JSON.stringify(s) }));
writeFileSync(out, JSON.stringify(cases));
console.log(`${cases.length} cases -> ${out}`);
EOF
